<?php get_header(); while (have_posts()) : the_post(); $id=get_the_ID(); ?>
<article class="ap-container single-part"><div class="gallery"><?php if (has_post_thumbnail()) { the_post_thumbnail('large'); } else { echo '<div class="no-photo">Фото скоро</div>'; } ?></div><div class="part-summary"><span class="eyebrow"><?php echo esc_html(get_post_meta($id,'_ap_stock_status',true) ?: 'Уточнить наличие'); ?></span><h1><?php the_title(); ?></h1><p class="part-meta"><?php echo esc_html(get_post_meta($id,'_ap_brand',true)); ?> <?php echo esc_html(get_post_meta($id,'_ap_model',true)); ?> <?php echo esc_html(get_post_meta($id,'_ap_generation',true)); ?></p><p class="oem">OEM: <?php echo esc_html(get_post_meta($id,'_ap_oem',true) ?: '—'); ?></p><strong class="single-price"><?php echo esc_html((string) apply_filters('autoparts_part_price', get_post_meta($id,'_ap_price',true), $id)); ?> <?php echo esc_html(get_post_meta($id,'_ap_currency',true) ?: 'USD'); ?></strong><div class="cta-row"><a href="#request" class="button-primary">Купить</a><a class="button-ghost" href="tel:<?php echo esc_attr(preg_replace('/\D+/', '', (string) (get_option('autoparts_settings', [])['phone'] ?? ''))); ?>">Позвонить</a></div></div><section class="part-details"><h2>Описание и характеристики</h2><?php the_content(); ?><ul><li>Состояние: <?php echo esc_html(get_post_meta($id,'_ap_condition',true)); ?></li><li>Гарантия: <?php echo esc_html(get_post_meta($id,'_ap_warranty',true)); ?></li><li>Склад: <?php echo esc_html(get_post_meta($id,'_ap_warehouse',true)); ?></li><li>Доставка: <?php echo get_post_meta($id,'_ap_delivery',true) ? 'да' : 'уточнить'; ?></li></ul></section><aside id="request"><?php echo do_shortcode('[autoparts_request_form part_id="' . absint($id) . '"]'); ?></aside></article>
<section class="ap-container"><h2>Похожие запчасти</h2><?php echo do_shortcode('[autoparts_catalog]'); ?></section>
<?php endwhile; get_footer(); ?>
